def firstEvenVowelIndex(s: str) -> int:
    vowels = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}
    mask = 0
    for i, ch in enumerate(s):
        if ch in vowels:
            mask ^= (1 << vowels[ch])
        if mask == 0:
            return i
    return -1

